import numpy as np

def compute_probabilities(max_n=100):
    p = np.zeros(max_n + 1)
    p[0] = 1.0  # P_0 = 1

    for n in range(1, max_n + 1):
        # Use recurrence: P_{n} = 8/3 * P_{n - 1} - 5/3 * P_{n - 2}
        if n == 1:
            p[n] = 1.0  # Starting from 1 head, we are looking for P_1
        else:
            p[n] = (8/3) * p[n - 1] - (5/3) * p[n - 2]

    return p

p_values = compute_probabilities(100)
p_1 = p_values[1]

